}

func TestTwoRegistriesOnOneHostKeepIndependentCheckboxes(t *testing.T) {
	m := oneHostModel(t)
	b := m.registryBrowser

	feed(t, m, testutil.Key("down"), testutil.Key(" "))

	if b.selected(b.entries[0]) {
