	}

	b.tags = nil
	b.registryFilter = resultFilter{}
	b.pendingSearches = 0
	b.filterInput.SetValue("")
	b.filterActive = false
	b.tagSortCol = tagSortByName
	b.tagSortDesc = false

	var cmds []tea.Cmd
	for _, entry := range b.entries {
		if !b.selectedRegs[entry.URL] {
			continue
		}
		username, storedPass := b.credsFor(entry)
		alias := entry.Alias
		if entry.ParentAlias != "" {
			alias = entry.ParentAlias + "/" + entry.Alias
		}
		normalizedRepo := normalizeRepoForRegistry(entry.URL, repo)
		apiURL := registryAPIURL(entry.URL)
		b.pendingSearches++
		cmds = append(cmds, searchRegistryTagsCmd(entry.URL, alias, apiURL, normalizedRepo, username, storedPass))
	}

	if len(cmds) == 0 {
		return b, nil
	}

	b.state = browserStateTags
	b.tagTable.Focus()
	b.rebuildTagTable()
	cmds = append(cmds, b.spinner.Tick)
	return b, tea.Batch(cmds...)
}

func (b *RegistryBrowser) handleTagsKeyMsg(msg tea.KeyMsg) (*RegistryBrowser, tea.Cmd) {
	if b.filterActive {
		switch msg.String() {
		case "esc", "enter":
			b.filterActive = false
			b.filterInput.Blur()
			b.rebuildTagTable()
			b.resizeTagTable()
			return b, nil
		}
		return b.delegateUpdate(msg)
	}

	switch msg.String() {
	case "esc":
		b.state = browserStateInput
		b.tagTable.Blur()
		b.updateFocus()
		return b, nil
	case "/":
		b.filterActive = true
		b.filterInput.Focus()
		b.resizeTagTable()
		return b, nil
	case ".":
		b.cycleSortTags()
		return b, nil
	case "r":
		b.cycleRegistryFilter()
		return b, nil
	case "up", "k":
		b.tagTable.MoveUp(1)
		return b, nil
	case "down", "j":
		b.tagTable.MoveDown(1)
		return b, nil
	case "g", "home":
		b.tagTable.GotoTop()
		return b, nil
	case "G", "end":
		b.tagTable.GotoBottom()
		return b, nil
	case "enter":
		return b.openTagScanDetails()
	case "p":
		return b.pullSelectedTag()
	case "ctrl+s":
		return b.requestDirectScan()
	}
	return b, nil
}

