16	// The search form and the results table, driven through the model — the router
17	// is what forwards keys to the browser, and the model is what wires the scan
18	// cache in. registry_browser_test.go covers opening, group resolution and the
19	// arrival of results; this file covers what the user does once it is open.
20	
21	// groupedModel returns a browser whose first registry resolved into a group of
22	// two members, so the entry list mixes members and a plain registry.
23	func groupedModel(t *testing.T) Model {
24		t.Helper()
25		m := feed(t, loadedModel(t), RegistryGroupCacheLoadedMsg{Entries: groupCacheFixture()})
26		return feed(t, m, testutil.Key("b"))
27	}
28	
29	func typeInto(t *testing.T, m Model, s string) Model {
30		t.Helper()
31		return feed(t, m, testutil.Type(s)...)
32	}
33	
34	// resultsModel returns a browser on its results screen, having actually
35	// submitted a search. searchedModel feeds tags in without submitting, which is
36	// enough to test where results land but leaves the browser on the form — the
37	// results table is only rebuilt while the tags screen is showing.
38	func resultsModel(t *testing.T, msgs ...tea.Msg) Model {
39		t.Helper()
40	
41		m := typeInto(t, browsingModel(t), "api")
42		m = feed(t, m, testutil.Key("enter"))
43		if m.registryBrowser.state != browserStateTags {
44			t.Fatalf("the search did not reach the results screen (state %d)", m.registryBrowser.state)
45		}
46		if len(msgs) == 0 {
47			msgs = []tea.Msg{
48				MultiRegistryTagsLoadedMsg{RegistryURL: "registry.example.com", Alias: "prod", Repo: "api", Tags: []string{"v1", "v2"}},
49				MultiRegistryTagsLoadedMsg{RegistryURL: "docker.io", Alias: "hub", Repo: "api", Tags: []string{"latest"}},
50			}
51		}
52		return feed(t, m, msgs...)
53	}
54	
55	// ── The search form ──────────────────────────────────────────────────────────
56	
57	// Rule 135: ↑ / ↓ walk the fields. They clamp rather than wrap here, so the
58	// list of registries can be walked without the focus jumping past its ends.
59	func TestTheFormWalksFromTheRepoThroughEveryRegistryToTheButton(t *testing.T) {
60		m := browsingModel(t)
61		b := m.registryBrowser
62	
63		if b.focusedField != brFieldRepo {
64			t.Fatalf("the form opened on field %d, want the repository", b.focusedField)
65		}
66		m = feed(t, m, testutil.Key("up"))
67		if b.focusedField != brFieldRepo {
68			t.Errorf("focus = %d, want it held on the first field", b.focusedField)
69		}
70	
71		for i := range b.entries {
72			m = feed(t, m, testutil.Key("down"))
73			if b.focusedField != b.brFieldReg(i) {
74				t.Fatalf("focus = %d, want the checkbox for entry %d", b.focusedField, i)
75			}
76		}
77		m = feed(t, m, testutil.Key("down"))
78		if b.focusedField != b.brFieldSubmit() {
79			t.Errorf("focus = %d, want the button", b.focusedField)
80		}
81		feed(t, m, testutil.Key("down"))
82		if b.focusedField != b.brFieldSubmit() {
83			t.Errorf("focus = %d, want it held on the button", b.focusedField)
84		}
85	}
86	
87	// Every registry starts checked: the common case is searching all of them, and
88	// an empty selection would make the button do nothing on open.
89	func TestEveryRegistryStartsSelected(t *testing.T) {
90		b := browsingModel(t).registryBrowser
91	
92		for _, entry := range b.entries {
93			if !b.selected(entry) {
94				t.Errorf("%s opened unchecked", entry.URL)
95			}
96		}
97	}
