99	// Rule 135: space is the only key that toggles a checkbox.
100	func TestSpaceTogglesTheFocusedRegistry(t *testing.T) {
101		m := browsingModel(t)
102		b := m.registryBrowser
103		first := b.entries[0]
104	
105		m = feed(t, m, testutil.Key("down"), testutil.Key(" "))
106		if b.selected(first) {
107			t.Error("space did not uncheck the focused registry")
108		}
109		feed(t, m, testutil.Key(" "))
110		if !b.selected(first) {
111			t.Error("space did not check it back")
112		}
113	}
114	
115	// Space on the repository field is a character, not a toggle — a repository
116	// name is text and the field has to take it.
117	func TestSpaceOnTheRepositoryFieldIsTyped(t *testing.T) {
