135	func TestEnterOnTheRepositoryFieldSearches(t *testing.T) {
136		m := typeInto(t, browsingModel(t), "nginx")
137	
138		m = feed(t, m, testutil.Key("enter"))
139	
140		if m.registryBrowser.state != browserStateTags {
141			t.Errorf("state = %d, want the results screen", m.registryBrowser.state)
142		}
143		if got := m.registryBrowser.pendingSearches; got != 2 {
144			t.Errorf("pendingSearches = %d, want one per selected registry", got)
145		}
146	}
147	
148	// On a checkbox, Enter advances instead — Rule 135 keeps it off the toggle, and
149	// it has to do something rather than nothing.
150	func TestEnterOnACheckboxAdvances(t *testing.T) {
151		m := typeInto(t, browsingModel(t), "nginx")
152		b := m.registryBrowser
153	
154		m = feed(t, m, testutil.Key("down"), testutil.Key("enter"))
155	
156		if b.state != browserStateInput {
157			t.Fatalf("enter on a checkbox started a search (state %d)", b.state)
158		}
159		if b.focusedField != b.brFieldReg(1) {
160			t.Errorf("focus = %d, want the next checkbox", b.focusedField)
161		}
162	}
163	
164	func TestSearchingWithNoRepositoryDoesNothing(t *testing.T) {
165		m := browsingModel(t)
166	
167		m = feed(t, m, testutil.Key("enter"))
168	
169		if m.registryBrowser.state != browserStateInput {
170			t.Errorf("state = %d, want the form still open", m.registryBrowser.state)
171		}
172		if m.registryBrowser.pendingSearches != 0 {
173			t.Error("a search was started with no repository")
174		}
175	}
